using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap a REST API using constructor-injected HttpClient.
/// The SDK resolves DI services (HttpClient, ILogger) automatically —
/// they never appear in the tool schema shown to LLMs.
/// </summary>
[McpServerToolType]
public class RestApiTools(HttpClient httpClient, ILogger<RestApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all resources from the REST API. Returns a JSON array.")]
    public async Task<string> ListResources(
        [Description("Maximum number of items to return (1–100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources (limit={Limit})", limit);
        var json = await httpClient.GetStringAsync($"/posts?_limit={limit}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a single resource by its numeric ID.")]
    public async Task<string> GetResource(
        [Description("The unique ID of the resource to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Create a new resource with a title and body.")]
    public async Task<string> CreateResource(
        [Description("Title for the new resource")] string title,
        [Description("Body content of the resource")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource: {Title}", title);
        var payload = JsonSerializer.Serialize(new { title, body, userId = 1 });
        var content = new StringContent(payload, Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

